    );



SetFunctionName("VecFloatRef<INDEX1>& SelfAdd(VecFloatRef<INDEX1> &a, VecFloat::InParam b)");

MakeVecRef( v1, X, 2.5f );
VecFloat v2(3.5f);
SelfAdd(v1, v2);
Validate( IsEqualWithEpsilon(v1, 6.0f) );



SetFunctionName("VecFloatRef<INDEX1>& SelfAdd(VecFloatRef<INDEX1> &a, VecFloatRef<INDEX2> b)");

MakeVecRef( v1, X, 2.5f );
MakeVecRef( v2, Y, 3.5f );
SelfAdd(v1, v2);
Validate( IsEqualWithEpsilon(v1, 6.0f) );



SetFunctionName("VecFloatRef<INDEX1>& SelfAdd(VecFloatRef<INDEX1> &a, VecFloatRefIndex::InParam b)");

MakeVecRef( v1, X, 2.5f );
MakeVectorIntrinsic(vi, 1.0f, 2.0f, 3.5f, 4.0f);
VecFloatRefIndex vr(vi, 2);
SelfAdd(v1, vr);
Validate( IsEqualWithEpsilon(v1, 6.0f) );



SetFunctionName("VecFloatRef<INDEX1>& SelfAdd(VecFloatRef<INDEX1> &a, const float& b)");

MakeVecRef( v1, X, 2.5f );
float f = 3.5f;
SelfAdd(v1, f);
Validate( IsEqualWithEpsilon(v1, 6.0f) );



